const QUESTIONS=[{id:1,skill:1,section:"1A",bullet:"copilot-privacy",topic:"Copilot Privacy",question:"What happens to your prompts and organizational data when you use Microsoft 365 Copilot?",options:["Microsoft stores prompts to improve the AI model","Prompts are shared with other tenants for better training","All data is encrypted during transmission and never stored or used for model training","Data is anonymized and added to the public training dataset"],correct:2,explanation:"All data is encrypted during transmission and user information is never stored or used for model training to ensure privacy. Microsoft does NOT use your prompts to train models.",source:{title:"Microsoft 365 Copilot as your workflow companion",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/4-copilot-workflow-companion",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:2,skill:1,section:"1A",bullet:"copilot-privacy",topic:"Copilot Privacy",question:"How does Copilot ensure that users only see data they are authorized to access?",options:["It creates separate AI models for each user","It respects existing Microsoft 365 permissions and security policies","It requires manual approval for every query","It only uses public web data by default"],correct:1,explanation:"Copilot respects the organization's existing permission model. If you don't have access to a document in SharePoint, Copilot won't surface that data in responses either.",source:{title:"Microsoft 365 Copilot as your workflow companion",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/4-copilot-workflow-companion",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:3,skill:1,section:"1A",bullet:"context-affects-responses",topic:"Context Affects Responses",question:"What is the correct order of data flow when you send a prompt to Microsoft 365 Copilot?",options:["Prompt → LLM → Response","Prompt → Microsoft Graph (pre-processing) → LLM → Microsoft Graph (post-processing) → Response","Prompt → Azure AI → SharePoint → Response","Prompt → Web search → LLM → Response"],correct:1,explanation:"The data flow is: User prompt → Microsoft Graph for pre-processing/grounding → LLM for generation → back to Microsoft Graph for post-processing to verify accuracy and reduce fabrications → response to user.",source:{title:"What is Copilot Chat?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/2-what-is-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:4,skill:1,section:"1A",bullet:"context-affects-responses",topic:"Context Affects Responses",question:"In Copilot Chat, what is the difference between 'Work' mode and 'Web' mode?",options:["Work mode is faster; Web mode is more accurate","Work mode accesses organizational data via Microsoft Graph; Web mode searches the public internet","Work mode requires a separate license; Web mode is always free","Work mode only works in Teams; Web mode works everywhere"],correct:1,explanation:"Work mode grounds responses in your organizational data (emails, files, chats) via Microsoft Graph. Web mode searches the public internet. Both use generative AI but access different data sources.",source:{title:"What is Copilot Chat?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/2-what-is-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:5,skill:1,section:"1A",bullet:"context-affects-responses",topic:"Context Affects Responses",question:"What is Microsoft Graph's role in the Copilot experience?",options:["It is the LLM that generates responses","It provides the organizational context by connecting emails, files, meetings, chats, and calendar data","It stores all Copilot conversations permanently","It manages Copilot licensing"],correct:1,explanation:"Microsoft Graph is the secure intelligence layer behind Microsoft 365. It connects your emails, files, meetings, calendar, chats, and collaboration activity to give Copilot context about your work.",source:{title:"What is Copilot Chat?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/2-what-is-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:6,skill:1,section:"1A",bullet:"chat-vs-agent",topic:"Chat vs Agent",question:"What is the key difference between a Copilot Chat experience and an agent experience?",options:["Chat is free; agents require payment","Chat handles general tasks across apps; agents are specialized for specific tasks with custom instructions and knowledge","Chat only works offline; agents only work online","Chat is for administrators; agents are for end users"],correct:1,explanation:"Copilot Chat is a general-purpose AI assistant across M365. Agents are specialized — they have custom instructions, specific knowledge sources, and are built for particular business tasks.",source:{title:"What are Copilot agents?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:7,skill:1,section:"1A",bullet:"create-own-agent",topic:"Creating Agents",question:"When should you create your own Copilot agent instead of using the built-in Copilot Chat?",options:["When you want faster responses","When you need a specialized tool with custom knowledge, instructions, and capabilities for a specific business process","When you need to access the internet","When you want to use Copilot without a license"],correct:1,explanation:"Create your own agent when you need it tailored to a specific business process — with custom knowledge sources, specific instructions, and defined capabilities that go beyond general Copilot Chat.",source:{title:"What are Copilot agents?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:8,skill:1,section:"1A",bullet:"copilot-across-apps",topic:"Copilot Across Apps",question:"How does the Copilot experience differ between Microsoft 365 apps?",options:["Copilot works identically in all apps","Each app has tailored Copilot features — Word for drafting, Excel for data analysis, Teams for meeting summaries, PowerPoint for presentations","Copilot only works in Word and Excel","The differences are only cosmetic; functionality is the same"],correct:1,explanation:"Copilot is embedded in each M365 app with features tailored to that app's purpose: drafting in Word, data analysis in Excel, meeting summarization in Teams, presentation creation in PowerPoint, email drafting in Outlook.",source:{title:"Microsoft 365 Copilot as your workflow companion",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/4-copilot-workflow-companion",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:9,skill:1,section:"1A",bullet:"copilot-across-apps",topic:"Copilot Across Apps",question:"What makes Copilot Chat different from Copilot embedded in specific M365 apps like Word or Excel?",options:["Copilot Chat is less powerful","Copilot Chat acts as a cross-app command center, connecting information across Word, Excel, Teams, and Outlook from a single interface","Copilot Chat can only access web data","There is no difference"],correct:1,explanation:"Copilot in apps focuses on tasks within that specific app. Copilot Chat is a cross-app command center — it connects information across multiple apps from a single conversation interface.",source:{title:"What is Copilot Chat?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/2-what-is-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:10,skill:1,section:"1B",bullet:"common-risks",topic:"Common Risks",question:"What is a 'fabrication' in the context of generative AI?",options:["When AI intentionally creates false information","When AI generates a convincing but incorrect response that isn't grounded in actual data","When AI copies content from the internet","When AI refuses to answer a question"],correct:1,explanation:"A fabrication (Microsoft's preferred term over 'hallucination') is when AI generates a response that sounds convincing but is incorrect — not grounded in actual data. The two-step grounding process via Microsoft Graph helps reduce this.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:11,skill:1,section:"1B",bullet:"common-risks",topic:"Common Risks",question:"What is 'prompt injection' as a risk in generative AI?",options:["When a user types too quickly into the prompt field","When malicious instructions are embedded in content to manipulate AI behavior or bypass safety controls","When a prompt is too long for the AI to process","When Copilot saves a prompt automatically"],correct:1,explanation:"Prompt injection is when malicious instructions are hidden in content (like documents or emails) to manipulate the AI into bypassing safety controls or producing unauthorized outputs.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:12,skill:1,section:"1B",bullet:"verification-steps",topic:"Verification Steps",question:"What should you always do after receiving a response from Copilot?",options:["Share it immediately with your team","Verify the output by checking citations, reviewing accuracy, and applying human judgment","Delete the conversation for security","Forward it to your manager for approval"],correct:1,explanation:"Never take Copilot's word for it — always verify. Check citations to confirm sources, review for accuracy, and apply human judgment. You are accountable for AI output, not the AI.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:13,skill:1,section:"1B",bullet:"verification-steps",topic:"Verification Steps",question:"What does the 'human in the loop' concept mean for Copilot usage?",options:["A human must write every prompt","Humans must remain involved in verifying, reviewing, and taking responsibility for AI-generated outputs","Only humans can start Copilot sessions","A human must approve every Copilot license"],correct:1,explanation:"Human in the loop means AI should never be completely hands-off. Humans must constantly verify answers, review outputs, and take responsibility. Copilot assists — it doesn't replace human judgment.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:14,skill:1,section:"1B",bullet:"sensitive-data-risks",topic:"Sensitive Data",question:"How does Microsoft 365 Copilot handle sensitive organizational data?",options:["It makes all data available to all users","It respects existing sensitivity labels, permissions, and data loss prevention policies","It automatically redacts all sensitive information","It requires manual classification of every document"],correct:1,explanation:"Copilot respects existing M365 security: sensitivity labels, permissions, and DLP policies. If a document has restricted access, Copilot won't surface it to unauthorized users.",source:{title:"Microsoft 365 Copilot as your workflow companion",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/4-copilot-workflow-companion",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:15,skill:1,section:"1B",bullet:"data-protection-restrictions",topic:"Data Protection",question:"What does 'privacy by design' mean in the context of Copilot?",options:["Privacy features are added after deployment","Security and privacy are built into the system architecture from the design phase, not added later","Users must configure their own privacy settings","Privacy only applies to enterprise customers"],correct:1,explanation:"Privacy by design means security and privacy protections are built into Copilot's architecture from the start — encryption, permission respect, data isolation — not bolted on afterward.",source:{title:"Microsoft 365 Copilot as your workflow companion",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/4-copilot-workflow-companion",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:16,skill:1,section:"1B",bullet:"common-risks",topic:"Common Risks",question:"What is the risk of 'over-reliance' on generative AI?",options:["The AI becomes slower over time","Users stop critically evaluating AI outputs and blindly trust everything Copilot generates","The organization runs out of Copilot licenses","Copilot stops generating new content"],correct:1,explanation:"Over-reliance means users trust AI outputs without verification. This is dangerous because Copilot can produce fabrications, reference outdated documents, or misinterpret context. Always verify.",source:{title:"Understand responsible AI",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/3-understand-responsible-ai",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:17,skill:1,section:"1B",bullet:"data-protection-restrictions",topic:"Data Protection",question:"If a user doesn't have permission to access a document in SharePoint, what happens when they ask Copilot about its contents?",options:["Copilot provides a summary anyway","Copilot asks an admin for temporary access","Copilot cannot surface that data — it respects existing access permissions","Copilot shows the document title but not the content"],correct:2,explanation:"Copilot respects the existing permission model. If you can't access a document directly, Copilot won't surface its content either. Permissions are enforced consistently.",source:{title:"Microsoft 365 Copilot as your workflow companion",url:"https://learn.microsoft.com/en-us/training/modules/what-generative-ai/4-copilot-workflow-companion",video:{title:"Episode 1: What is generative AI?",url:"https://www.youtube.com/watch?v=bIqV5jilJKk"}}},{id:18,skill:2,section:"2A",bullet:"effective-prompts",topic:"Effective Prompts",question:"What are the four parts of an effective Copilot prompt according to Microsoft?",options:["Subject, Body, Signature, Attachment","Goal, Context, Source, Expectations","Question, Answer, Feedback, Rating","Input, Process, Output, Review"],correct:1,explanation:"Four parts: Goal (what you want), Context (who you are and why), Source (what documents/data to use), Expectations (format, tone, length). This is heavily tested on the exam.",source:{title:"Write effective prompts",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/3-write-effective-prompts-optimize-copilot-responses",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:19,skill:2,section:"2A",bullet:"effective-prompts",topic:"Effective Prompts",question:"Which prompt is more effective for getting useful Copilot output?",options:["'Write something about the project'","'Draft a 3-paragraph executive summary of the Q4 marketing report, using a professional tone, and highlight key revenue metrics'","'Help me'","'Make a document'"],correct:1,explanation:"Effective prompts include all four parts: Goal (executive summary), Context (Q4 marketing report), Source (implied), Expectations (3 paragraphs, professional tone, revenue metrics). Vague prompts produce vague results.",source:{title:"Write effective prompts",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/3-write-effective-prompts-optimize-copilot-responses",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:20,skill:2,section:"2A",bullet:"effective-prompts",topic:"Effective Prompts",question:"In the prompt 'Focus on emails and Teams chats since June', which prompt component does this represent?",options:["Goal","Context","Source","Expectations"],correct:2,explanation:"This specifies the Source — where Copilot should look for information. Goal = what you want, Context = who/why, Source = where to look, Expectations = format/tone.",source:{title:"Write effective prompts",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/3-write-effective-prompts-optimize-copilot-responses",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:21,skill:2,section:"2A",bullet:"reference-resources",topic:"Referencing Resources",question:"How can you reference a specific file in a Copilot prompt?",options:["Type the full file path manually","Use the / command or attach button to reference specific files, emails, or meetings","Email the file to Copilot first","You cannot reference specific files"],correct:1,explanation:"In Copilot Chat, you can use the / command or the attach/plus button to reference specific files from OneDrive, SharePoint, recent emails, or meetings — grounding the response in those specific sources.",source:{title:"Write effective prompts",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/3-write-effective-prompts-optimize-copilot-responses",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:22,skill:2,section:"2A",bullet:"reference-resources",topic:"Referencing Resources",question:"Why is it beneficial to reference specific documents in your Copilot prompt?",options:["It makes the prompt shorter","It grounds the response in specific, relevant data rather than general knowledge, improving accuracy","It's required for every prompt","It reduces licensing costs"],correct:1,explanation:"Referencing specific documents grounds the response in your actual business data. Without specific references, Copilot may use general knowledge or wrong documents, reducing accuracy.",source:{title:"Write effective prompts",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/3-write-effective-prompts-optimize-copilot-responses",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:23,skill:2,section:"2A",bullet:"save-prompt",topic:"Save Prompt",question:"Where can you find and manage your saved prompts in Copilot Chat?",options:["In the Windows Start menu","In the Prompts Gallery or your saved prompts section within Copilot","In a separate Microsoft app","In your email inbox"],correct:1,explanation:"Saved prompts are accessible from the Prompts Gallery in Copilot Chat. You can save prompts you use frequently and access them later to reuse without retyping.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:24,skill:2,section:"2A",bullet:"schedule-prompt",topic:"Schedule Prompt",question:"What is the purpose of scheduling a prompt in Copilot?",options:["To delay sending an email","To have Copilot automatically run a prompt on a recurring schedule (daily, weekly) and deliver results","To set a reminder to use Copilot later","To batch multiple prompts together"],correct:1,explanation:"Scheduled prompts run automatically at set times — daily morning briefings, weekly status updates, etc. Organizational settings may impact availability of scheduled prompts.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:25,skill:2,section:"2A",bullet:"share-prompt",topic:"Share Prompt",question:"How can you share a useful prompt with colleagues?",options:["Screenshot it and email the image","Share it directly from the Prompts Gallery or copy and distribute the prompt text","You cannot share prompts","Only admins can share prompts"],correct:1,explanation:"Prompts can be shared from the Prompts Gallery. This helps teams standardize their AI usage and ensures everyone benefits from well-crafted prompts.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:26,skill:2,section:"2B",bullet:"find-conversations",topic:"Find Conversations",question:"How can you find a previous conversation in Copilot Chat?",options:["You cannot — conversations are deleted after each session","Use the chat history panel on the left side, organized by date, or use the search function","Check your email — conversations are emailed to you","Only IT admins can retrieve past conversations"],correct:1,explanation:"By default, all Copilot Chat conversations are saved in the chat history on the left panel, organized by time periods. You can search through them or browse by date.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:27,skill:2,section:"2B",bullet:"delete-chat",topic:"Delete Chat",question:"What happens when you use 'Temporary Chat' mode in Copilot?",options:["The chat runs faster","The conversation is not saved in your chat history","The chat is shared with everyone in your organization","You can only use Web mode"],correct:1,explanation:"Temporary Chat mode means the conversation will not be saved in your chat history. Use this for one-off queries you don't need to reference later.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:28,skill:2,section:"2B",bullet:"rename-chat",topic:"Rename Chat",question:"Why would you rename a Copilot Chat conversation?",options:["To change the AI model being used","To make it easier to find and organize in your chat history","To share it with other users","Renaming is required by organizational policy"],correct:1,explanation:"Renaming conversations helps you organize your chat history so you can quickly find relevant past interactions instead of scrolling through auto-generated titles.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:29,skill:2,section:"2B",bullet:"add-to-notebook",topic:"Add to Notebook",question:"What is the purpose of adding a Copilot conversation to a Notebook?",options:["To print the conversation","To organize deep research and complex projects with multiple prompts in a persistent workspace","To delete the original conversation","To convert it to an email"],correct:1,explanation:"Notebooks are for deep research and complex projects. Adding a conversation to a Notebook preserves it in a persistent workspace where you can organize multiple prompts and continue analysis.",source:{title:"Enhance collaboration with Chat, Pages, and Notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:30,skill:2,section:"2C",bullet:"agent-store-vs-create",topic:"Agent Store vs Create",question:"When should you use an agent from the Agent Store instead of creating your own?",options:["Always — custom agents are not allowed","When a pre-built agent already meets your needs, saving time and effort","Only when your organization doesn't have Copilot Studio","Never — the Agent Store is only for testing"],correct:1,explanation:"Use the Agent Store when a pre-built agent already handles your use case. Only create a custom agent when you need specific instructions, knowledge, or capabilities not available in existing agents.",source:{title:"What are Copilot agents?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:31,skill:2,section:"2C",bullet:"create-agent-template",topic:"Create Agent Template",question:"How can you create a Copilot agent without writing any code?",options:["You cannot — all agents require coding","Use a template in Copilot Studio or the M365 Copilot agent builder with natural language descriptions","Ask Microsoft to build it for you","Export an Excel file as an agent"],correct:1,explanation:"Copilot Studio provides templates and a no-code/low-code builder. You can describe what you want the agent to do in natural language, select a template, and customize from there.",source:{title:"What are Copilot agents?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:32,skill:2,section:"2C",bullet:"configure-agent-knowledge",topic:"Agent Knowledge",question:"What does it mean to configure an agent 'with knowledge'?",options:["Teaching the agent a programming language","Connecting the agent to specific data sources (SharePoint sites, files, websites) so it can answer questions about that content","Giving the agent internet access","Increasing the agent's processing speed"],correct:1,explanation:"Configuring knowledge means connecting specific data sources (SharePoint sites, uploaded files, websites) to the agent. This grounds the agent's responses in your actual business content.",source:{title:"What are Copilot agents?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:33,skill:2,section:"2C",bullet:"configure-agent-settings",topic:"Agent Settings",question:"Which of the following can you configure when setting up a Copilot agent?",options:["Only the agent's name","Instructions (behavior), capabilities (what it can do), and suggested prompts (starter questions)","Only the data sources","Only the visual appearance"],correct:1,explanation:"Agent settings include: Instructions (how it should behave, its role, tasks), Capabilities (what actions it can perform), and Suggested prompts (starter questions to help users get started).",source:{title:"What are Copilot agents?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:34,skill:2,section:"2C",bullet:"share-agent",topic:"Share Agent",question:"How can you make a custom Copilot agent available to your team?",options:["Email the agent's code to each team member","Share the agent through the Agent Store or directly with team members, controlling who has access","Post the agent on a public website","You cannot share custom agents"],correct:1,explanation:"Custom agents can be shared through the Agent Store within your organization or directly with specific team members. You control who has access to the agent.",source:{title:"What are Copilot agents?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:35,skill:2,section:"2A",bullet:"effective-prompts",topic:"Effective Prompts",question:"In the prompt component framework, what does 'Expectations' refer to?",options:["What you expect the AI to learn","The desired output format, tone, length, or style of the response","How long you expect to wait for a response","The cost you expect to pay"],correct:1,explanation:"Expectations define how you want the output: format (bullet points, table, paragraph), tone (professional, casual), length (brief, detailed), or specific constraints (use simple language).",source:{title:"Write effective prompts",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/3-write-effective-prompts-optimize-copilot-responses",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:36,skill:2,section:"2A",bullet:"effective-prompts",topic:"Effective Prompts",question:"What is the Prompts Gallery in Copilot Chat?",options:["A collection of AI-generated images","A library of pre-built prompt templates organized by task type and job role that you can use and save","A gallery of previous conversation screenshots","A marketplace to buy premium prompts"],correct:1,explanation:"The Prompts Gallery provides pre-built prompt templates filtered by task type and job role. You can browse, use, and save these prompts for your own workflow.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:37,skill:2,section:"2B",bullet:"find-conversations",topic:"Find Conversations",question:"What response modes are available in Copilot Chat?",options:["Only standard mode","Auto (default), Quick Response (faster), and Think Deeper (longer, uses deep search)","Basic and Premium modes","Text only and Multimedia modes"],correct:1,explanation:"Copilot Chat offers: Auto (default — decides response depth automatically), Quick Response (faster, shorter), and Think Deeper (longer, more thorough, uses deep search).",source:{title:"What is Copilot Chat?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/2-what-is-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:38,skill:2,section:"2C",bullet:"agent-store-vs-create",topic:"Agent Store",question:"Where can you browse available pre-built agents in Microsoft 365?",options:["In the Microsoft Store app","In the Agents section of Copilot Chat, accessible from the left panel","Only through the IT admin portal","In the Windows Settings"],correct:1,explanation:"Pre-built agents are accessible from the Agents section in the Copilot Chat interface. You can browse and activate agents that fit your needs from there.",source:{title:"What are Copilot agents?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:39,skill:2,section:"2A",bullet:"schedule-prompt",topic:"Schedule Prompt",question:"A sales manager wants to receive an automatic summary of their team's activities every Monday morning. What Copilot feature should they use?",options:["Set a calendar reminder to open Copilot","Schedule a prompt to run automatically every Monday and deliver the summary","Ask an assistant to run the prompt manually","Create a Power Automate flow"],correct:1,explanation:"Scheduled prompts automate recurring tasks. The manager can set a prompt to run every Monday morning, automatically generating and delivering the team activity summary.",source:{title:"Manage prompts and conversations",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4-manage-prompts-conversations-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:40,skill:2,section:"2C",bullet:"configure-agent-knowledge",topic:"Agent Knowledge",question:"A company wants to create an agent that answers HR policy questions. What knowledge sources should they connect?",options:["The company's public website only","The HR policy SharePoint site and employee handbook documents","Wikipedia and public HR resources","Individual employee email inboxes"],correct:1,explanation:"The agent should be connected to the organization's specific HR policy documents (SharePoint site, employee handbook). This grounds responses in actual company policies, not generic HR information.",source:{title:"What are Copilot agents?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/4a-copilot-agents-defined",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:41,skill:2,section:"2A",bullet:"reference-resources",topic:"Referencing Resources",question:"What sources can you attach or reference when writing a prompt in Copilot Chat with a M365 Copilot license?",options:["Only OneDrive files","Cloud files from OneDrive/SharePoint, uploaded images, and work content from M365 apps","Only web URLs","Only locally saved files on your computer"],correct:1,explanation:"With a M365 Copilot license, you can reference cloud files (OneDrive/SharePoint), upload images, and reference work content from across M365 apps to ground your prompt in specific data.",source:{title:"What is Copilot Chat?",url:"https://learn.microsoft.com/en-us/training/modules/employ-copilot-assistant/2-what-is-copilot-chat",video:{title:"Episode 2: Copilot Chat as your AI assistant",url:"https://www.youtube.com/watch?v=Nc0jM8lh9II"}}},{id:42,skill:3,section:"3A",bullet:"create-doc-from-prompt",topic:"Create Doc from Prompt",question:"How can you use Copilot in Word to create a new document from scratch?",options:["Only by copying text from Copilot Chat","Open a blank Word document and use the Copilot 'Draft with Copilot' feature to describe what you want","You must have an existing template first","Only through the mobile app"],correct:1,explanation:"In Word, the 'Draft with Copilot' feature lets you describe what you want in a prompt, and Copilot generates a first draft. You can then refine and edit the output.",source:{title:"Draft your content using Copilot",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/2-draft-content-using-copilot",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:43,skill:3,section:"3A",bullet:"generate-from-existing",topic:"Generate from Existing",question:"A manager has a 30-page project report and needs a 2-page executive brief. How should they use Copilot?",options:["Manually copy-paste the key sections","Reference the existing report in Copilot and ask it to generate a concise executive summary","Delete pages until only 2 remain","Ask a colleague to summarize it"],correct:1,explanation:"Reference the existing document in your Copilot prompt and ask it to generate a summary or brief. Copilot can distill long documents into concise summaries while preserving key insights.",source:{title:"Draft your content using Copilot",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/2-draft-content-using-copilot",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:44,skill:3,section:"3A",bullet:"management-summary",topic:"Management Summary",question:"What is the Researcher agent in Microsoft 365 Copilot best used for?",options:["Analyzing Excel data and creating charts","Gathering information from documents, synthesizing research, and enhancing documents with deeper insights","Managing meeting schedules","Creating PowerPoint animations"],correct:1,explanation:"The Researcher agent gathers information from documents, websites, and PDFs to synthesize research and enhance your documents with deeper insights. For data/Excel analysis, use the Analyst agent.",source:{title:"Research and gather information using the Researcher Agent",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/3-research-gather-researcher-agent",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:45,skill:3,section:"3A",bullet:"management-summary",topic:"Management Summary",question:"What is the Analyst agent best used for?",options:["Drafting emails and documents","Analyzing data in Excel, generating insights, creating visualizations, and building charts","Managing team permissions","Scheduling meetings"],correct:1,explanation:"The Analyst agent specializes in data analysis: working with Excel data, generating insights, creating visualizations and charts. It uses code interpreter and can generate Python code for complex analysis.",source:{title:"Generate insights using the Analyst Agent",url:"https://learn.microsoft.com/en-us/training/modules/analyze-visualize-data-copilot/3-generate-insights-analyst-agent",video:{title:"Episode 4: Analyze and visualize data",url:"https://www.youtube.com/watch?v=l8gj-ICwQRs"}}},{id:46,skill:3,section:"3A",bullet:"move-data-between-apps",topic:"Move Data Between Apps",question:"A user creates a data analysis in Excel Copilot and wants to include the results in a PowerPoint presentation. What can they do?",options:["Re-do the analysis manually in PowerPoint","Use Copilot to move insights between apps — export from Excel and create slides in PowerPoint referencing the data","Take a screenshot and paste it","This is not possible between Microsoft apps"],correct:1,explanation:"Copilot supports moving data and insights between M365 apps. You can reference Excel data when creating PowerPoint presentations, or use Copilot Chat to synthesize content across multiple app outputs.",source:{title:"Draft your content using Copilot",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/2-draft-content-using-copilot",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:47,skill:3,section:"3A",bullet:"create-doc-from-prompt",topic:"Create Doc from Prompt",question:"What types of content can Copilot in Word help you draft?",options:["Only formal business letters","Emails, proposals, reports, blog posts, summaries, and virtually any text-based document","Only templates provided by Microsoft","Only meeting minutes"],correct:1,explanation:"Copilot in Word can draft any text-based content: emails, proposals, reports, blog posts, summaries, policy documents, creative writing, and more. It then lets you refine the output.",source:{title:"Draft your content using Copilot",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/2-draft-content-using-copilot",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:48,skill:3,section:"3A",bullet:"generate-from-existing",topic:"Generate from Existing",question:"How can Copilot in PowerPoint help create a presentation from an existing document?",options:["It cannot — you must create slides manually","Reference a Word document or other file and Copilot generates a presentation deck from its content","It only adds clipart to existing slides","You must first convert the document to PDF"],correct:1,explanation:"Copilot in PowerPoint can take an existing Word document, report, or outline and generate a full presentation from it — creating slides, adding relevant content, and structuring the deck.",source:{title:"Build a client proposal deck",url:"https://learn.microsoft.com/en-us/training/modules/define-copilot-role-business-workflow/3-build-client-proposal-deck",video:{title:"Episode 6: Define Copilot role in your workflow",url:"https://www.youtube.com/watch?v=ULBebaSF7Bw"}}},{id:49,skill:3,section:"3B",bullet:"copilot-for-meetings",topic:"Copilot for Meetings",question:"What can Copilot do during a Microsoft Teams meeting?",options:["Only record the meeting","Capture real-time insights, automate note-taking, summarize discussions, and identify action items","Only display subtitles","Only manage the participant list"],correct:1,explanation:"Copilot in Teams meetings captures real-time insights, automates note-taking, summarizes discussions, identifies action items, and can generate post-meeting summaries and follow-up emails.",source:{title:"Streamline meeting preparation and follow-ups",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/2-streamline-meeting-prep",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:50,skill:3,section:"3B",bullet:"copilot-for-meetings",topic:"Copilot for Meetings",question:"After a Teams meeting, what can Copilot generate automatically?",options:["Only a recording link","A meeting summary, key discussion points, decisions made, action items, and follow-up email drafts","Only the list of attendees","Only the meeting duration"],correct:1,explanation:"Post-meeting, Copilot generates summaries of key discussion points, decisions, and action items. It can also draft follow-up emails to send to participants.",source:{title:"Streamline meeting preparation and follow-ups",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/2-streamline-meeting-prep",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:51,skill:3,section:"3B",bullet:"copilot-pages",topic:"Copilot Pages",question:"What is the primary purpose of Copilot Pages?",options:["Managing Copilot licenses","Real-time collaborative workspace where team members can edit, refine, and build on AI-generated content together","Storing Copilot settings","Creating website pages"],correct:1,explanation:"Copilot Pages is a collaborative workspace — like a shared document where team members can edit, refine, and build on AI-generated content together in real time.",source:{title:"Enhance collaboration with Chat, Pages, and Notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:52,skill:3,section:"3B",bullet:"copilot-pages",topic:"Copilot Pages",question:"What is the difference between Copilot Pages and Copilot Notebooks?",options:["They are the same feature with different names","Pages are for quick, real-time collaboration; Notebooks are for deep research and complex projects with organized prompts","Pages are for admins; Notebooks are for users","Pages are free; Notebooks require premium license"],correct:1,explanation:"Pages = quick collaboration (like a shared doc for team editing). Notebooks = deep research workspace (organized prompts, complex multi-document projects). Different tools for different needs.",source:{title:"Enhance collaboration with Chat, Pages, and Notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:53,skill:3,section:"3B",bullet:"copilot-memory",topic:"Copilot Memory",question:"What does Copilot's memory feature allow it to do?",options:["Remember conversations from other users","Remember your preferences, instructions, and context across conversations to provide more personalized responses","Store unlimited files permanently","Access other organizations' data"],correct:1,explanation:"Copilot memory allows it to remember your preferences, working style, and instructions across sessions, providing more personalized and context-aware responses over time.",source:{title:"Enhance collaboration with Chat, Pages, and Notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:54,skill:3,section:"3A",bullet:"move-data-between-apps",topic:"Move Data Between Apps",question:"A consultant needs to prepare a weekly status report using data from Excel, email summaries from Outlook, and meeting notes from Teams. What approach should they take?",options:["Open each app separately and manually compile the report","Use Copilot Chat in Work mode to synthesize information across all M365 apps and draft the report","Only use the Excel data since other apps aren't supported","Ask each team member to submit their own section"],correct:1,explanation:"Copilot Chat in Work mode acts as a cross-app command center. It can pull data from Excel, Outlook emails, and Teams meeting notes to synthesize a comprehensive status report.",source:{title:"Prepare weekly status report",url:"https://learn.microsoft.com/en-us/training/modules/define-copilot-role-business-workflow/2-prepare-weekly-status-report",video:{title:"Episode 6: Define Copilot role in your workflow",url:"https://www.youtube.com/watch?v=ULBebaSF7Bw"}}},{id:55,skill:3,section:"3A",bullet:"management-summary",topic:"Management Summary",question:"What is the best approach when using Copilot to create an executive summary?",options:["Let Copilot generate it and send immediately without review","Reference the source document, specify the audience and format, then review and refine the output","Copy the first paragraph of the source document","Ask Copilot to search the web for a template"],correct:1,explanation:"Best practice: reference the specific source document, specify your audience (executives) and format expectations, let Copilot draft it, then review and refine before sending.",source:{title:"Create an executive summary",url:"https://learn.microsoft.com/en-us/training/modules/define-copilot-role-business-workflow/4-create-executive-summary",video:{title:"Episode 6: Define Copilot role in your workflow",url:"https://www.youtube.com/watch?v=ULBebaSF7Bw"}}},{id:56,skill:3,section:"3B",bullet:"copilot-for-meetings",topic:"Copilot for Meetings",question:"How can Copilot help with meeting preparation?",options:["It cannot help before meetings, only during","Summarize related email threads, pull relevant documents, and create briefing notes before the meeting","Only by sending calendar invites","Only by testing the audio/video connection"],correct:1,explanation:"Before meetings, Copilot can summarize related email threads, find relevant documents, catch you up on project context, and create briefing notes so you walk in prepared.",source:{title:"Streamline meeting preparation and follow-ups",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/2-streamline-meeting-prep",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:57,skill:3,section:"3A",bullet:"create-doc-from-prompt",topic:"Create Doc from Prompt",question:"Copilot in Outlook can help with which of the following tasks?",options:["Only reading emails","Drafting email replies, summarizing long email threads, and adjusting the tone of messages","Only sorting emails by date","Only managing calendar events"],correct:1,explanation:"Copilot in Outlook can draft new emails, generate replies, summarize long threads, adjust tone (professional, casual), and help prioritize your inbox.",source:{title:"Draft your content using Copilot",url:"https://learn.microsoft.com/en-us/training/modules/draft-refine-business-content/2-draft-content-using-copilot",video:{title:"Episode 3: Draft and refine business content",url:"https://www.youtube.com/watch?v=O9Fx8lVdYtc"}}},{id:58,skill:3,section:"3A",bullet:"generate-from-existing",topic:"Generate from Existing",question:"What can Copilot in Excel do with your data?",options:["Only sort columns","Analyze data, identify trends, create formulas, generate charts, and provide insights through natural language questions","Only format cells","Only import data from external sources"],correct:1,explanation:"Copilot in Excel can analyze data, identify trends, suggest and create formulas, generate visualizations/charts, and answer questions about your data in natural language.",source:{title:"Analyze data workflows in Excel",url:"https://learn.microsoft.com/en-us/training/modules/analyze-visualize-data-copilot/2-analyze-data-workflows-excel",video:{title:"Episode 4: Analyze and visualize data",url:"https://www.youtube.com/watch?v=l8gj-ICwQRs"}}},{id:59,skill:3,section:"3B",bullet:"copilot-memory",topic:"Copilot Memory",question:"How can you give Copilot specific instructions about how to work with you?",options:["You cannot customize Copilot's behavior","Through the memory and instructions settings, where you can set preferences like communication style, role context, and recurring needs","Only by contacting Microsoft support","Only through your IT department"],correct:1,explanation:"Copilot's memory and instructions feature lets you set persistent preferences: your role, communication style, recurring needs, and specific instructions that carry across conversations.",source:{title:"Enhance collaboration with Chat, Pages, and Notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}},{id:60,skill:3,section:"3B",bullet:"copilot-pages",topic:"Copilot Pages",question:"Where can you access your created Copilot Pages and images?",options:["Only in the Teams app","In the Library section of Copilot Chat","Only through SharePoint","Only on mobile devices"],correct:1,explanation:"The Library section in Copilot Chat stores your created Pages and generated images. You can review, edit, and share them from there.",source:{title:"Enhance collaboration with Chat, Pages, and Notebooks",url:"https://learn.microsoft.com/en-us/training/modules/manage-meetings-collaboration/3-enhance-collaboration-chat-pages-notebooks",video:{title:"Episode 5: Manage meetings and collaboration",url:"https://www.youtube.com/watch?v=9fMVHrON8cs"}}}],SKILL_DISTRIBUTION={1:{name:"Understand generative AI fundamentals",weight:"25-30%",count:17},2:{name:"Manage prompts and conversations by using AI",weight:"35-40%",count:24},3:{name:"Draft and analyze business content by using AI",weight:"25-30%",count:19}};